insert into public.questions (exam_category, subject, topic, type, difficulty, body, body_hi, question_data, options, marks_correct, marks_wrong, explanation, explanation_hi, concept_group_id, source_type, source_citation, status)
values
('upsc','Science & Technology','Energy & Environmental Technology','statement_based','medium','Consider the following statements about ethanol blending in India:','भारत में एथेनॉल मिश्रण के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["India reached 20 per cent blending of ethanol in petrol in 2025.", "Under the programme, oil marketing companies buy ethanol from distilleries.", "Blending ethanol raises the energy content of each litre of fuel."], "statements_hi": ["भारत 2025 में पेट्रोल में 20 प्रतिशत एथेनॉल मिश्रण तक पहुँच गया।", "कार्यक्रम के तहत तेल विपणन कंपनियाँ आसवनियों (distilleries) से एथेनॉल ख़रीदती हैं।", "एथेनॉल मिलाने से ईंधन के प्रति लीटर ऊर्जा की मात्रा बढ़ती है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct: the E20 goal, first set for 2030, was brought forward and met in 2025, cutting crude imports and paying sugarcane and grain growers. Statement 3 is wrong: ethanol carries about a third less energy per litre than petrol, so mileage falls slightly on blended fuel -- although its high octane rating helps engines tuned for it.','कथन 1 और 2 सही हैं: E20 का लक्ष्य, जो पहले 2030 के लिए था, आगे लाया गया और 2025 में पूरा हुआ, जिससे कच्चे तेल का आयात घटा और गन्ना तथा अनाज उत्पादकों को भुगतान मिला। कथन 3 गलत है: एथेनॉल में पेट्रोल से प्रति लीटर लगभग एक-तिहाई कम ऊर्जा होती है, इसलिए मिश्रित ईंधन पर माइलेज थोड़ा घटता है, यद्यपि इसकी ऊँची ऑक्टेन रेटिंग इसके अनुरूप बने इंजनों की मदद करती है।','en-ethanol-blending','original_pattern_matched','Ministry of Petroleum and Natural Gas -- Ethanol Blended Petrol Programme; NITI Aayog -- Roadmap for Ethanol Blending (2021).','draft'),
('upsc','Science & Technology','Energy & Environmental Technology','statement_based','medium','Consider the following statements about compressed biogas:','संपीड़ित बायोगैस (CBG) के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Under the SATAT initiative, compressed biogas plants sell their gas to oil marketing companies.", "Compressed biogas is made up mostly of hydrogen.", "Compressed biogas is produced by burning crop residue in the open air."], "statements_hi": ["SATAT पहल के तहत संपीड़ित बायोगैस संयंत्र अपनी गैस तेल विपणन कंपनियों को बेचते हैं।", "संपीड़ित बायोगैस मुख्य रूप से हाइड्रोजन से बनी होती है।", "संपीड़ित बायोगैस खुले में फ़सल अवशेष जलाकर बनाई जाती है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": true}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 1 is correct: SATAT (2018) assures a buyer and a price for gas made from farm waste, cattle dung, press mud and municipal waste. Statement 2 is wrong: after purification it is over 90 per cent methane, so it can replace CNG in vehicles and piped gas. Statement 3 is wrong: it comes from anaerobic digestion -- bacteria breaking down wet waste without oxygen -- and the leftover slurry is a useful manure; using crop residue this way is an alternative to stubble burning.','केवल कथन 1 सही है: SATAT (2018) कृषि अपशिष्ट, गोबर, प्रेस मड और नगरीय कचरे से बनी गैस के लिए ख़रीदार और क़ीमत सुनिश्चित करता है। कथन 2 गलत है: शुद्ध करने के बाद यह 90 प्रतिशत से अधिक मीथेन होती है, इसलिए वाहनों और पाइप गैस में CNG का स्थान ले सकती है। कथन 3 गलत है: यह अवायवीय पाचन (anaerobic digestion) से बनती है, यानी जीवाणु ऑक्सीजन के बिना गीले कचरे को तोड़ते हैं, और बची हुई घोल (slurry) उपयोगी खाद है; फ़सल अवशेष का इस तरह उपयोग पराली जलाने का विकल्प है।','en-compressed-biogas-satat','original_pattern_matched','Ministry of Petroleum and Natural Gas -- SATAT (Sustainable Alternative Towards Affordable Transportation).','draft'),
('upsc','Science & Technology','Energy & Environmental Technology','statement_based','medium','Consider the following statements about nuclear power:','नाभिकीय ऊर्जा के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["The Union Budget 2025-26 announced a Nuclear Energy Mission with ₹20,000 crore for small modular reactors.", "India aims at 100 GW of nuclear power capacity by 2047.", "Each small modular reactor produces more power than a conventional large reactor.", "Small modular reactors are designed to be built largely in factories and shipped as modules."], "statements_hi": ["केंद्रीय बजट 2025-26 ने लघु मॉड्यूलर रिएक्टरों के लिए ₹20,000 करोड़ के साथ एक नाभिकीय ऊर्जा मिशन की घोषणा की।", "भारत का लक्ष्य 2047 तक 100 GW नाभिकीय ऊर्जा क्षमता है।", "हर लघु मॉड्यूलर रिएक्टर एक पारंपरिक बड़े रिएक्टर से अधिक बिजली पैदा करता है।", "लघु मॉड्यूलर रिएक्टर बड़े पैमाने पर कारख़ानों में बनाकर मॉड्यूल के रूप में भेजे जाने के लिए बनाए गए हैं।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "Only three", "body_hi": "केवल तीन", "isCorrect": true}, {"id": "d", "body": "All four", "body_hi": "सभी चार", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1, 2 and 4 are correct: the mission aims to have at least five indigenously designed SMRs working by 2033, and factory building is meant to cut costs and construction time; SMRs could also replace retiring coal units at existing sites. Statement 3 is wrong: SMRs are small by design -- typically up to about 300 MW, against 700-1,000 MW or more for large reactors.','कथन 1, 2 और 4 सही हैं: मिशन का लक्ष्य 2033 तक कम से कम पाँच स्वदेशी रूप से डिज़ाइन किए गए SMR चालू करना है, और कारख़ाने में निर्माण का उद्देश्य लागत और निर्माण समय घटाना है; SMR मौजूदा स्थलों पर सेवानिवृत्त होती कोयला इकाइयों का स्थान भी ले सकते हैं। कथन 3 गलत है: SMR डिज़ाइन से ही छोटे हैं, प्रायः लगभग 300 MW तक, जबकि बड़े रिएक्टर 700-1,000 MW या अधिक के होते हैं।','en-nuclear-mission-smr','original_pattern_matched','Ministry of Finance -- Union Budget 2025-26, Budget Speech; Department of Atomic Energy.','draft'),
('upsc','Science & Technology','Energy & Environmental Technology','statement_based','medium','Consider the following statements about nuclear fusion:','नाभिकीय संलयन (nuclear fusion) के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["ITER, the international fusion experiment, is being built in France, and India is one of its members.", "Fusion releases energy by joining light nuclei, such as isotopes of hydrogen.", "India''s contributions to ITER include the cryostat, a giant steel vessel that surrounds the reactor."], "statements_hi": ["अंतरराष्ट्रीय संलयन प्रयोग, ITER, फ़्रांस में बनाया जा रहा है, और भारत इसके सदस्यों में से एक है।", "संलयन हाइड्रोजन के समस्थानिकों जैसे हल्के नाभिकों को जोड़कर ऊर्जा छोड़ता है।", "ITER में भारत के योगदान में क्रायोस्टैट शामिल है, जो रिएक्टर को घेरने वाला इस्पात का एक विशाल पात्र है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": true}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'All three statements are correct. ITER uses a tokamak, which holds plasma hotter than the Sun''s core in a magnetic cage; India contributes components in kind and shares the results, alongside the EU, China, Japan, Korea, Russia and the United States. The cryostat was built by an Indian firm. Fusion still produces no electricity commercially.','तीनों कथन सही हैं। ITER एक टोकामक का उपयोग करता है, जो सूर्य के केंद्र से अधिक गर्म प्लाज़्मा को एक चुंबकीय पिंजरे में रखता है; भारत EU, चीन, जापान, कोरिया, रूस और संयुक्त राज्य अमेरिका के साथ घटकों के रूप में योगदान देता है और परिणामों में साझेदार है। क्रायोस्टैट एक भारतीय कंपनी ने बनाया। संलयन अभी वाणिज्यिक रूप से बिजली नहीं देता।','en-fusion-iter','original_pattern_matched','ITER Organization; Department of Atomic Energy -- ITER-India, Institute for Plasma Research.','draft'),
('upsc','Science & Technology','Energy & Environmental Technology','statement_based','medium','Consider the following statements about pumped storage:','पंप्ड स्टोरेज के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["A pumped storage plant pumps water to an upper reservoir when power is cheap and releases it through turbines when power is needed.", "It is a mature technology that has been in use for decades.", "A pumped storage plant can switch from pumping to generating within minutes, helping to balance the grid."], "statements_hi": ["पंप्ड स्टोरेज संयंत्र बिजली सस्ती होने पर पानी को ऊपरी जलाशय में पंप करता है और ज़रूरत पड़ने पर उसे टरबाइनों से छोड़ता है।", "यह एक परिपक्व तकनीक है जो दशकों से उपयोग में है।", "पंप्ड स्टोरेज संयंत्र मिनटों में पंप करने से उत्पादन की ओर बदल सकता है, जिससे ग्रिड को संतुलित करने में मदद मिलती है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": true}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'All three statements are correct. The plant is a giant water battery that soaks up surplus solar power by day and generates in the evening peak; it gives back about three-quarters of the energy it uses, so it is a store, not a source. India is building many such projects to firm up its renewable power.','तीनों कथन सही हैं। संयंत्र एक विशाल जल-बैटरी है जो दिन में अतिरिक्त सौर ऊर्जा सोखती है और शाम के चरम पर उत्पादन करती है; यह ली गई ऊर्जा का लगभग तीन-चौथाई लौटाता है, इसलिए यह भंडार है, स्रोत नहीं। भारत अपनी नवीकरणीय ऊर्जा को स्थिर करने के लिए ऐसी कई परियोजनाएँ बना रहा है।','en-pumped-storage','original_pattern_matched','Central Electricity Authority -- Guidelines on Pumped Storage Projects; Ministry of Power.','draft'),
('upsc','Science & Technology','Energy & Environmental Technology','statement_based','medium','Consider the following statements about electric mobility:','विद्युत गतिशीलता (electric mobility) के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Battery swapping lets a driver exchange a discharged battery for a charged one instead of waiting to recharge.", "The PM E-DRIVE scheme of 2024 took over from FAME-II as the Centre''s main scheme for EV incentives.", "Most electric two-wheelers in India run on hydrogen fuel cells."], "statements_hi": ["बैटरी अदला-बदली (battery swapping) चालक को रिचार्ज की प्रतीक्षा के बजाय डिस्चार्ज बैटरी को चार्ज बैटरी से बदलने देती है।", "2024 की PM E-DRIVE योजना ने EV प्रोत्साहनों के लिए केंद्र की मुख्य योजना के रूप में FAME-II का स्थान लिया।", "भारत में अधिकांश इलेक्ट्रिक दोपहिया वाहन हाइड्रोजन ईंधन सेलों से चलते हैं।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct: swapping suits e-rickshaws and delivery scooters that cannot sit idle, and PM E-DRIVE supports two- and three-wheelers, e-buses, e-ambulances, e-trucks and charging stations. Statement 3 is wrong: electric two-wheelers run on lithium-ion batteries; fuel cells are being tried mainly in buses and heavy trucks.','कथन 1 और 2 सही हैं: अदला-बदली उन ई-रिक्शा और डिलीवरी स्कूटरों के लिए उपयुक्त है जो खड़े नहीं रह सकते, और PM E-DRIVE दोपहिया और तिपहिया, ई-बसों, ई-एम्बुलेंस, ई-ट्रकों और चार्जिंग स्टेशनों को सहायता देती है। कथन 3 गलत है: इलेक्ट्रिक दोपहिया लिथियम-आयन बैटरियों से चलते हैं; ईंधन सेलों को मुख्य रूप से बसों और भारी ट्रकों में आज़माया जा रहा है।','en-electric-mobility','original_pattern_matched','Ministry of Heavy Industries -- PM E-DRIVE scheme (2024); NITI Aayog -- battery swapping policy.','draft'),
('upsc','Science & Technology','Energy & Environmental Technology','statement_based','medium','Consider the following statements about energy efficiency:','ऊर्जा दक्षता के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["A heat pump moves heat rather than generating it, so it can deliver more heat energy than the electricity it uses.", "Under the Bureau of Energy Efficiency''s labels, appliances that consume more power get more stars.", "The LED bulbs given out under UJALA mainly replaced sodium vapour lamps in people''s homes."], "statements_hi": ["ऊष्मा पंप (heat pump) ऊष्मा पैदा करने के बजाय उसे स्थानांतरित करता है, इसलिए यह अपने द्वारा प्रयुक्त बिजली से अधिक ऊष्मा ऊर्जा दे सकता है।", "ऊर्जा दक्षता ब्यूरो के लेबलों में अधिक बिजली ख़र्च करने वाले उपकरणों को अधिक स्टार मिलते हैं।", "उजाला (UJALA) के तहत बाँटे गए LED बल्बों ने मुख्य रूप से लोगों के घरों में सोडियम वाष्प लैंपों का स्थान लिया।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": true}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 1 is correct: like a refrigerator run in reverse, a heat pump draws warmth from outside air or water, typically delivering three or four units of heat for each unit of electricity. Statement 2 is wrong: more stars mean less energy used for the same service. Statement 3 is wrong: UJALA''s LEDs, given out from 2015, replaced incandescent bulbs and CFLs in homes; sodium lamps were street lights, replaced under a separate street-lighting programme.','केवल कथन 1 सही है: उलटा चलाए गए रेफ़्रिजरेटर की तरह, ऊष्मा पंप बाहरी हवा या पानी से गर्मी खींचता है और प्रायः बिजली की हर इकाई पर तीन-चार इकाई ऊष्मा देता है। कथन 2 गलत है: अधिक स्टार का अर्थ है उसी सेवा के लिए कम ऊर्जा। कथन 3 गलत है: 2015 से बाँटे गए उजाला के LED ने घरों में तापदीप्त बल्बों और CFL का स्थान लिया; सोडियम लैंप सड़क की बत्तियाँ थे, जिन्हें एक अलग सड़क-प्रकाश कार्यक्रम के तहत बदला गया।','en-energy-efficiency','original_pattern_matched','Bureau of Energy Efficiency -- Standards and Labelling; Energy Efficiency Services Limited -- UJALA.','draft'),
('upsc','Science & Technology','Energy & Environmental Technology','statement_based','medium','Consider the following statements about desalination by reverse osmosis:','विपरीत परासरण (reverse osmosis) से विलवणीकरण के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Reverse osmosis uses no energy.", "Reverse osmosis works by boiling water and condensing the steam.", "The reject water from a reverse osmosis plant is less salty than the water fed into it."], "statements_hi": ["विपरीत परासरण में कोई ऊर्जा नहीं लगती।", "विपरीत परासरण पानी उबालकर और भाप को संघनित करके काम करता है।", "विपरीत परासरण संयंत्र से निकलने वाला अस्वीकृत पानी (reject water) उसमें डाले गए पानी से कम खारा होता है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": true}]'::jsonb,2,0.66,'None of the statements is correct. Pumps push water at high pressure through a membrane that holds back salts -- the pressure is where the energy goes. Boiling and condensing is distillation, a different method. The salts left behind make the reject brine saltier than the input, and disposing of it, whether from coastal plants such as Chennai''s or household purifiers, is an environmental problem.','कोई भी कथन सही नहीं है। पंप पानी को ऊँचे दाब पर एक झिल्ली से धकेलते हैं जो लवणों को रोक लेती है; ऊर्जा इसी दाब में लगती है। उबालना और संघनित करना आसवन है, एक अलग विधि। पीछे छूटे लवण अस्वीकृत खारे पानी को डाले गए पानी से अधिक खारा बना देते हैं, और इसका निपटान, चाहे चेन्नई जैसे तटीय संयंत्रों से हो या घरेलू शोधकों से, एक पर्यावरणीय समस्या है।','en-reverse-osmosis-none','original_pattern_matched','Ministry of Jal Shakti; National Institute of Ocean Technology -- desalination.','draft'),
('upsc','Science & Technology','Energy & Environmental Technology','statement_based','medium','Consider the following statements about solar power technologies:','सौर ऊर्जा प्रौद्योगिकियों के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Bifacial solar panels can capture sunlight on both their front and back surfaces.", "Solar panels work more efficiently as they get hotter.", "Concentrated solar power uses mirrors to focus sunlight and produce heat that drives turbines."], "statements_hi": ["द्विमुखी (bifacial) सौर पैनल अपनी आगे और पीछे, दोनों सतहों पर धूप पकड़ सकते हैं।", "सौर पैनल जितने अधिक गर्म होते हैं, उतनी अधिक कुशलता से काम करते हैं।", "सांद्रित सौर ऊर्जा (CSP) धूप केंद्रित करने के लिए दर्पणों का उपयोग करती है और ऐसी ऊष्मा पैदा करती है जो टरबाइन चलाती है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 3 are correct: bifacial panels gain from light reflected off the ground, especially over pale surfaces, and CSP can store heat in molten salt to generate after sunset. Statement 2 is wrong: silicon panels lose output as their temperature rises -- roughly 0.4 per cent per degree -- which is why they yield less on very hot days than on cool, bright ones.','कथन 1 और 3 सही हैं: द्विमुखी पैनल ज़मीन से परावर्तित प्रकाश से, विशेषकर हल्के रंग की सतहों पर, लाभ पाते हैं, और CSP सूर्यास्त के बाद उत्पादन के लिए ऊष्मा को पिघले लवण में संग्रहीत कर सकती है। कथन 2 गलत है: तापमान बढ़ने पर सिलिकॉन पैनलों का उत्पादन घटता है, लगभग 0.4 प्रतिशत प्रति डिग्री; इसीलिए वे बहुत गर्म दिनों में ठंडे, चमकीले दिनों से कम बिजली देते हैं।','en-solar-technologies','original_pattern_matched','Ministry of New and Renewable Energy; National Institute of Solar Energy.','draft'),
('upsc','Science & Technology','Energy & Environmental Technology','statement_based','medium','Consider the following statements about energy from waste:','कचरे से ऊर्जा के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Waste-to-energy plants burn municipal solid waste to generate electricity.", "Refuse-derived fuel is made from the dry, combustible part of municipal waste.", "Cement kilns can use refuse-derived fuel as a partial substitute for coal."], "statements_hi": ["कचरे से ऊर्जा (waste-to-energy) संयंत्र बिजली पैदा करने के लिए नगरीय ठोस कचरा जलाते हैं।", "कचरा-व्युत्पन्न ईंधन (refuse-derived fuel) नगरीय कचरे के सूखे, ज्वलनशील भाग से बनता है।", "सीमेंट भट्ठे कोयले के आंशिक विकल्प के रूप में कचरा-व्युत्पन्न ईंधन का उपयोग कर सकते हैं।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": true}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'All three statements are correct. The plants work well only if waste is segregated: Indian waste is wet and low in calorific value, and several plants have struggled or faced complaints about emissions. The very high temperatures in cement kilns destroy most pollutants, so ''co-processing'' there is a cleaner outlet for plastics that cannot be recycled.','तीनों कथन सही हैं। संयंत्र तभी अच्छा काम करते हैं जब कचरा अलग किया गया हो: भारतीय कचरा गीला और कम ऊष्मीय मान वाला है, और कई संयंत्रों को कठिनाइयाँ या उत्सर्जन की शिकायतें झेलनी पड़ी हैं। सीमेंट भट्ठों के अत्यधिक ऊँचे तापमान अधिकांश प्रदूषकों को नष्ट कर देते हैं, इसलिए वहाँ ''सह-प्रसंस्करण'' उन प्लास्टिकों के लिए स्वच्छ मार्ग है जिन्हें पुनर्चक्रित नहीं किया जा सकता।','en-waste-to-energy-rdf','original_pattern_matched','Ministry of Housing and Urban Affairs -- Swachh Bharat Mission (Urban) guidance on RDF; Central Pollution Control Board.','draft'),
('upsc','Science & Technology','Energy & Environmental Technology','statement_based','medium','Consider the following statements about nano fertilisers:','नैनो उर्वरकों के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Nano urea is a liquid fertiliser developed by IFFCO.", "Nano urea is applied mainly by mixing it into the soil before sowing.", "Nano DAP contains no phosphorus."], "statements_hi": ["नैनो यूरिया IFFCO द्वारा विकसित एक द्रव उर्वरक है।", "नैनो यूरिया मुख्य रूप से बुआई से पहले मिट्टी में मिलाकर डाला जाता है।", "नैनो DAP में कोई फ़ॉस्फ़ोरस नहीं होता।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": true}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 1 is correct: launched in 2021, it is meant to cut the use -- and the import and subsidy burden -- of granular urea. Statement 2 is wrong: nano urea is sprayed on the leaves of a growing crop, which absorb the tiny particles. Statement 3 is wrong: nano DAP supplies both nitrogen and phosphorus, like conventional di-ammonium phosphate. Field trials have questioned how far nano fertilisers can replace granular ones, so they are recommended as a supplement.','केवल कथन 1 सही है: 2021 में शुरू हुआ यह दानेदार यूरिया का उपयोग, और उसके आयात तथा सब्सिडी का बोझ, घटाने के लिए है। कथन 2 गलत है: नैनो यूरिया बढ़ती फ़सल की पत्तियों पर छिड़का जाता है, जो सूक्ष्म कणों को सोख लेती हैं। कथन 3 गलत है: नैनो DAP पारंपरिक डाइ-अमोनियम फ़ॉस्फ़ेट की तरह नाइट्रोजन और फ़ॉस्फ़ोरस, दोनों देता है। खेत परीक्षणों ने प्रश्न उठाए हैं कि नैनो उर्वरक दानेदार उर्वरकों का कितना स्थान ले सकते हैं, इसलिए इन्हें पूरक के रूप में सुझाया जाता है।','en-nano-fertilisers','original_pattern_matched','Department of Fertilizers; IFFCO; Indian Council of Agricultural Research.','draft'),
('upsc','Science & Technology','Energy & Environmental Technology','statement_based','medium','Consider the following statements about hydrogen fuel cells:','हाइड्रोजन ईंधन सेलों के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["A fuel cell produces electricity by burning hydrogen in a flame.", "The only by-product of a hydrogen fuel cell is carbon dioxide.", "A fuel cell has to be recharged from the grid, like a battery."], "statements_hi": ["ईंधन सेल हाइड्रोजन को लौ में जलाकर बिजली पैदा करता है।", "हाइड्रोजन ईंधन सेल का एकमात्र उप-उत्पाद कार्बन डाइऑक्साइड है।", "ईंधन सेल को बैटरी की तरह ग्रिड से रिचार्ज करना पड़ता है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": true}]'::jsonb,2,0.66,'None of the statements is correct. A fuel cell combines hydrogen and oxygen electrochemically, without combustion, to give electricity, heat and water -- water being the only exhaust. It runs as long as it is fed with fuel, so a fuel-cell vehicle is refuelled with hydrogen in minutes rather than plugged in.','कोई भी कथन सही नहीं है। ईंधन सेल हाइड्रोजन और ऑक्सीजन को बिना दहन के, विद्युत-रासायनिक रूप से मिलाकर बिजली, ऊष्मा और पानी देता है; पानी ही एकमात्र निकास है। यह तब तक चलता है जब तक इसे ईंधन मिलता रहे, इसलिए ईंधन-सेल वाहन को प्लग में लगाने के बजाय कुछ मिनटों में हाइड्रोजन से भरा जाता है।','en-fuel-cells-none','original_pattern_matched','Ministry of New and Renewable Energy; NCERT Chemistry, Class XII -- Electrochemistry.','draft'),
('upsc','Science & Technology','Energy & Environmental Technology','statement_based','medium','Consider the following ways of storing energy:','ऊर्जा संग्रहीत करने के निम्नलिखित तरीक़ों पर विचार कीजिए:','{"statements": ["Flywheels store energy as rotational motion.", "Compressed-air storage stores energy by pumping air into underground caverns under pressure.", "Supercapacitors can charge and discharge much faster than batteries.", "Green hydrogen can store surplus renewable energy for long periods."], "statements_hi": ["फ़्लाईव्हील ऊर्जा को घूर्णन गति के रूप में संग्रहीत करते हैं।", "संपीड़ित-वायु भंडारण हवा को दाब में भूमिगत गुफाओं में पंप करके ऊर्जा संग्रहीत करता है।", "सुपरकैपेसिटर बैटरियों से कहीं तेज़ चार्ज और डिस्चार्ज हो सकते हैं।", "हरित हाइड्रोजन अतिरिक्त नवीकरणीय ऊर्जा को लंबी अवधि तक संग्रहीत कर सकती है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "Only three", "body_hi": "केवल तीन", "isCorrect": false}, {"id": "d", "body": "All four", "body_hi": "सभी चार", "isCorrect": true}]'::jsonb,2,0.66,'All four statements are correct. Each suits a different job: flywheels and supercapacitors give short, fast bursts that steady the grid''s frequency; compressed air and pumped water store energy for hours; hydrogen can hold it for weeks or seasons, though much energy is lost in converting power to hydrogen and back. A student who expects one of four to be wrong will be drawn to ''Only three''.','चारों कथन सही हैं। हर एक अलग काम के लिए उपयुक्त है: फ़्लाईव्हील और सुपरकैपेसिटर छोटे, तेज़ झटके देते हैं जो ग्रिड की आवृत्ति स्थिर करते हैं; संपीड़ित हवा और पंप किया गया पानी घंटों तक ऊर्जा संग्रहीत करते हैं; हाइड्रोजन इसे सप्ताहों या मौसमों तक रख सकती है, यद्यपि बिजली को हाइड्रोजन में और वापस बदलने में बहुत ऊर्जा नष्ट होती है। जो विद्यार्थी चार में से एक को गलत मानकर चलता है, वह ''केवल तीन'' की ओर खिंचेगा।','en-energy-storage-types','original_pattern_matched','Central Electricity Authority; International Energy Agency -- Energy storage.','draft'),
('upsc','Science & Technology','Energy & Environmental Technology','statement_based','medium','Consider the following statements about vehicles:','वाहनों के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Regenerative braking recovers energy when a vehicle slows down.", "A hybrid vehicle runs only on its battery and has no engine.", "Electric vehicles charged at home normally draw direct current straight from the wall socket.", "An electric car has more moving parts in its drivetrain than a petrol car."], "statements_hi": ["पुनर्योजी ब्रेकिंग (regenerative braking) वाहन के धीमा होने पर ऊर्जा वापस प्राप्त करती है।", "हाइब्रिड वाहन केवल अपनी बैटरी से चलता है और उसमें कोई इंजन नहीं होता।", "घर पर चार्ज होने वाले इलेक्ट्रिक वाहन सामान्यतः दीवार के सॉकेट से सीधे दिष्ट धारा (DC) लेते हैं।", "इलेक्ट्रिक कार की ड्राइवट्रेन में पेट्रोल कार से अधिक चलने वाले पुर्ज़े होते हैं।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": true}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "Only three", "body_hi": "केवल तीन", "isCorrect": false}, {"id": "d", "body": "All four", "body_hi": "सभी चार", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 1 is correct: the motor runs as a generator when braking, charging the battery. Statement 2 is wrong: a hybrid combines an engine with a battery and motor. Statement 3 is wrong: household sockets supply alternating current, which the car''s onboard charger converts; public fast chargers supply direct current. Statement 4 is wrong: an electric motor has far fewer moving parts than an engine with its gearbox, which lowers maintenance.','केवल कथन 1 सही है: ब्रेक लगाते समय मोटर जनरेटर की तरह चलकर बैटरी चार्ज करती है। कथन 2 गलत है: हाइब्रिड एक इंजन को बैटरी और मोटर के साथ मिलाता है। कथन 3 गलत है: घरेलू सॉकेट प्रत्यावर्ती धारा (AC) देते हैं, जिसे कार का अंतर्निहित चार्जर बदलता है; सार्वजनिक तेज़ चार्जर दिष्ट धारा देते हैं। कथन 4 गलत है: विद्युत मोटर में गियरबॉक्स वाले इंजन से कहीं कम चलने वाले पुर्ज़े होते हैं, जिससे रखरखाव घटता है।','en-vehicle-technology','original_pattern_matched','Ministry of Heavy Industries; Bureau of Energy Efficiency -- EV charging guidelines.','draft'),
('upsc','Science & Technology','Energy & Environmental Technology','statement_based','easy','Consider the following statements:','निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Solar and wind are renewable sources of energy.", "Burning coal releases carbon dioxide."], "statements_hi": ["सौर और पवन ऊर्जा के नवीकरणीय स्रोत हैं।", "कोयला जलाने से कार्बन डाइऑक्साइड निकलती है।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": true}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2,0.66,'Both statements are correct: sunlight and wind are replenished naturally, while coal is carbon that has been stored underground for millions of years and is released as CO2 when burnt.','दोनों कथन सही हैं: धूप और हवा प्राकृतिक रूप से नवीकृत होती रहती हैं, जबकि कोयला लाखों वर्षों से भूमिगत संग्रहीत कार्बन है, जो जलाने पर CO2 के रूप में निकलता है।','en-renewables-coal-easy','original_pattern_matched','NCERT Science, Class X -- Sources of Energy.','draft'),
('upsc','Science & Technology','Energy & Environmental Technology','statement_based','easy','Consider the following statements:','निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["LED bulbs save electricity compared with ordinary filament bulbs.", "Wind turbines burn coal to turn their blades."], "statements_hi": ["LED बल्ब साधारण तंतु वाले बल्बों की तुलना में बिजली बचाते हैं।", "पवन टरबाइन अपने ब्लेड घुमाने के लिए कोयला जलाते हैं।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": true}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 1 is correct. Statement 2 is wrong: the moving air itself turns the blades, which drive a generator; no fuel is burnt, which is why wind power produces no smoke.','केवल कथन 1 सही है। कथन 2 गलत है: चलती हवा स्वयं ब्लेड घुमाती है, जो एक जनरेटर चलाते हैं; कोई ईंधन नहीं जलता, इसीलिए पवन ऊर्जा से धुआँ नहीं निकलता।','en-led-wind-easy','original_pattern_matched','NCERT Science, Class X -- Sources of Energy.','draft'),
('upsc','Science & Technology','Energy & Environmental Technology','statement_based','easy','Consider the following statements:','निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Geothermal energy comes from the Sun''s heat stored in the oceans.", "Biogas can be made from cattle dung."], "statements_hi": ["भूतापीय (geothermal) ऊर्जा महासागरों में संग्रहीत सूर्य की ऊष्मा से आती है।", "बायोगैस गोबर से बनाई जा सकती है।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": true}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 2 is correct. Statement 1 is wrong: geothermal energy is heat from inside the Earth, reaching the surface in hot springs and geysers, as at Puga in Ladakh.','केवल कथन 2 सही है। कथन 1 गलत है: भूतापीय ऊर्जा पृथ्वी के भीतर की ऊष्मा है, जो गर्म झरनों और गीज़रों में सतह तक पहुँचती है, जैसे लद्दाख के पुगा में।','en-geothermal-biogas-easy','original_pattern_matched','NCERT Science, Class X -- Sources of Energy.','draft'),
('upsc','Science & Technology','Energy & Environmental Technology','statement_based','easy','Consider the following statements:','निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["A battery produces energy out of nothing.", "A solar panel must be connected to the grid before it can produce any electricity."], "statements_hi": ["बैटरी शून्य से ऊर्जा पैदा करती है।", "सौर पैनल को कोई भी बिजली पैदा करने से पहले ग्रिड से जोड़ना अनिवार्य है।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": true}]'::jsonb,2,0.66,'Neither statement is correct. A battery stores energy as chemical energy and gives back what was put in -- energy cannot be created. A solar panel produces electricity whenever light falls on it, which is why off-grid solar lamps and pumps work in remote villages.','कोई भी कथन सही नहीं है। बैटरी ऊर्जा को रासायनिक ऊर्जा के रूप में संग्रहीत करती है और उतनी ही लौटाती है जितनी डाली गई; ऊर्जा पैदा नहीं की जा सकती। सौर पैनल जब भी उस पर प्रकाश पड़े, बिजली पैदा करता है; इसीलिए ग्रिड से अलग सौर लैंप और पंप दूर के गाँवों में काम करते हैं।','en-battery-solar-easy','original_pattern_matched','NCERT Science, Class X -- Sources of Energy.','draft'),
('upsc','Science & Technology','Energy & Environmental Technology','statement_based','hard','Consider the following statements about emissions from electricity sources:','बिजली के स्रोतों से उत्सर्जन के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Over their life cycle, nuclear and wind power emit roughly similar amounts of carbon dioxide per unit of electricity.", "Hydropower reservoirs can emit methane as flooded vegetation decays.", "Gas-fired power plants emit more carbon dioxide per unit of electricity than coal-fired plants."], "statements_hi": ["अपने जीवन-चक्र में नाभिकीय और पवन ऊर्जा बिजली की प्रति इकाई लगभग समान मात्रा में कार्बन डाइऑक्साइड छोड़ती हैं।", "जलविद्युत जलाशय डूबी वनस्पति के सड़ने से मीथेन छोड़ सकते हैं।", "गैस-आधारित बिजली संयंत्र कोयला-आधारित संयंत्रों से बिजली की प्रति इकाई अधिक कार्बन डाइऑक्साइड छोड़ते हैं।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct: counting mining, construction and decommissioning, both nuclear and wind come to around 10-15 grams of CO2 per kWh, far below fossil fuels; reservoir emissions are highest in warm tropical regions. Statement 3 is wrong: gas plants emit roughly half as much CO2 per kWh as coal plants, though methane leaks along the gas supply chain reduce that advantage.','कथन 1 और 2 सही हैं: खनन, निर्माण और सेवामुक्ति को गिनने पर नाभिकीय और पवन दोनों लगभग 10-15 ग्राम CO2 प्रति kWh पर आते हैं, जो जीवाश्म ईंधनों से कहीं नीचे है; जलाशयों का उत्सर्जन गर्म उष्णकटिबंधीय क्षेत्रों में सबसे अधिक है। कथन 3 गलत है: गैस संयंत्र कोयला संयंत्रों की तुलना में प्रति kWh लगभग आधी CO2 छोड़ते हैं, यद्यपि गैस आपूर्ति शृंखला में मीथेन रिसाव यह लाभ घटाते हैं।','en-lifecycle-emissions','original_pattern_matched','Intergovernmental Panel on Climate Change -- AR5 Working Group III, Annex III; International Energy Agency.','draft'),
('upsc','Science & Technology','Energy & Environmental Technology','statement_based','hard','Consider the following statements about power grids:','बिजली ग्रिडों के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["''Grid-forming'' inverters can help keep a grid stable when a large share of power comes from solar and wind.", "The inertia that steadies a grid''s frequency comes mainly from solar panels.", "High-voltage direct current (HVDC) lines lose more power over long distances than alternating current lines."], "statements_hi": ["''ग्रिड-फ़ॉर्मिंग'' इन्वर्टर तब ग्रिड को स्थिर रखने में मदद कर सकते हैं जब बिजली का बड़ा भाग सौर और पवन से आता है।", "ग्रिड की आवृत्ति को स्थिर रखने वाला जड़त्व (inertia) मुख्य रूप से सौर पैनलों से आता है।", "उच्च-वोल्टेज दिष्ट धारा (HVDC) लाइनें लंबी दूरी पर प्रत्यावर्ती धारा लाइनों से अधिक बिजली खोती हैं।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": true}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 1 is correct: such inverters set their own voltage and frequency, mimicking the behaviour of conventional generators. Statement 2 is wrong: inertia comes from the heavy spinning turbines of thermal, hydro and nuclear plants, which resist sudden changes; solar panels have no moving parts, so a grid with fewer turbines needs other ways to stay stable. Statement 3 is wrong: over long distances HVDC loses less power, which is why it is used to carry bulk power from distant renewable zones and in undersea links.','केवल कथन 1 सही है: ऐसे इन्वर्टर पारंपरिक जनरेटरों के व्यवहार की नक़ल करते हुए अपना वोल्टेज और आवृत्ति स्वयं तय करते हैं। कथन 2 गलत है: जड़त्व ताप, जल और नाभिकीय संयंत्रों के भारी घूमते टरबाइनों से आता है, जो अचानक बदलावों का प्रतिरोध करते हैं; सौर पैनलों में कोई चलने वाला पुर्ज़ा नहीं होता, इसलिए कम टरबाइनों वाले ग्रिड को स्थिर रहने के अन्य तरीक़े चाहिए। कथन 3 गलत है: लंबी दूरी पर HVDC कम बिजली खोता है; इसीलिए इसका उपयोग दूर के नवीकरणीय क्षेत्रों से भारी मात्रा में बिजली लाने और समुद्र के नीचे के संपर्कों में होता है।','en-grid-inertia-hvdc','original_pattern_matched','Central Electricity Authority; Grid Controller of India; International Energy Agency.','draft'),
('upsc','Science & Technology','Energy & Environmental Technology','statement_based','hard','Consider the following statements about critical minerals:','महत्त्वपूर्ण (critical) खनिजों के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Inferred lithium resources were reported in the Reasi district of Jammu and Kashmir in 2023.", "India launched a National Critical Mineral Mission in 2025.", "Khanij Bidesh India Limited (KABIL) was set up to secure critical minerals from abroad."], "statements_hi": ["2023 में जम्मू-कश्मीर के रियासी ज़िले में लिथियम के अनुमानित संसाधनों की सूचना मिली।", "भारत ने 2025 में एक राष्ट्रीय महत्त्वपूर्ण खनिज मिशन शुरू किया।", "खनिज बिदेश इंडिया लिमिटेड (KABIL) विदेश से महत्त्वपूर्ण खनिज सुरक्षित करने के लिए बनाई गई।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": true}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'All three statements are correct. Lithium, cobalt, nickel and graphite are essential for batteries and clean-energy equipment, and India imports nearly all of them. KABIL, a joint venture of three public sector firms, has taken up lithium exploration blocks in Argentina; the mission covers exploration, auctions, processing and recycling.','तीनों कथन सही हैं। लिथियम, कोबाल्ट, निकेल और ग्रेफ़ाइट बैटरियों और स्वच्छ-ऊर्जा उपकरणों के लिए आवश्यक हैं, और भारत इनका लगभग पूरा आयात करता है। तीन सार्वजनिक क्षेत्र की कंपनियों के संयुक्त उद्यम KABIL ने अर्जेंटीना में लिथियम अन्वेषण खंड लिए हैं; मिशन अन्वेषण, नीलामी, प्रसंस्करण और पुनर्चक्रण को शामिल करता है।','en-critical-minerals','original_pattern_matched','Ministry of Mines -- National Critical Mineral Mission (2025); Geological Survey of India; KABIL.','draft'),
('upsc','Science & Technology','Energy & Environmental Technology','statement_based','hard','Consider the following statements about renewable power:','नवीकरणीय बिजली के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["A wind turbine''s output keeps rising with wind speed, without any upper limit.", "The levelised cost of electricity leaves out the cost of building the plant.", "Round-the-clock renewable power can be supplied without any storage or complementary source."], "statements_hi": ["पवन टरबाइन का उत्पादन हवा की गति के साथ बिना किसी ऊपरी सीमा के बढ़ता रहता है।", "बिजली की समतलीकृत लागत (levelised cost of electricity) में संयंत्र बनाने की लागत शामिल नहीं होती।", "चौबीसों घंटे नवीकरणीय बिजली बिना किसी भंडारण या पूरक स्रोत के दी जा सकती है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": true}]'::jsonb,2,0.66,'None of the statements is correct. Turbines reach their rated output at moderate wind speeds and are shut down in very strong winds to avoid damage. The levelised cost spreads the whole lifetime cost -- construction, finance, fuel and maintenance -- over the electricity produced, which is why it allows solar, wind and coal to be compared. Solar and wind vary with weather and time of day, so round-the-clock supply needs storage, hydro or other firm power alongside them.','कोई भी कथन सही नहीं है। टरबाइन मध्यम हवा की गति पर अपने निर्धारित उत्पादन तक पहुँचते हैं और बहुत तेज़ हवा में क्षति से बचने के लिए बंद कर दिए जाते हैं। समतलीकृत लागत पूरी जीवन-भर की लागत, यानी निर्माण, वित्त, ईंधन और रखरखाव, को उत्पादित बिजली पर फैलाती है; इसीलिए इससे सौर, पवन और कोयले की तुलना हो पाती है। सौर और पवन मौसम और दिन के समय के साथ बदलते हैं, इसलिए चौबीसों घंटे आपूर्ति के लिए उनके साथ भंडारण, जलविद्युत या अन्य स्थिर बिजली चाहिए।','en-renewables-concepts-none','original_pattern_matched','Ministry of New and Renewable Energy; Central Electricity Authority; International Renewable Energy Agency.','draft'),
('upsc','Science & Technology','Energy & Environmental Technology','mcq','medium','''Second-generation'' (2G) ethanol is made mainly from:','''दूसरी पीढ़ी'' (2G) का एथेनॉल मुख्य रूप से किससे बनाया जाता है?','{}'::jsonb,'[{"id": "a", "body": "sugarcane juice pressed from the stalks of the crop", "body_hi": "फ़सल के तनों से निकाले गए गन्ने के रस से", "isCorrect": false}, {"id": "b", "body": "maize and broken rice grains bought from the market", "body_hi": "बाज़ार से ख़रीदे गए मक्के और टूटे चावल के दानों से", "isCorrect": false}, {"id": "c", "body": "crop residues such as rice straw", "body_hi": "धान के पुआल जैसे फ़सल अवशेषों से", "isCorrect": true}, {"id": "d", "body": "molasses left over after sugar has been extracted", "body_hi": "चीनी निकालने के बाद बचे शीरे (molasses) से", "isCorrect": false}]'::jsonb,2,0.66,'First-generation ethanol uses sugar and starch from food crops; 2G ethanol breaks down the cellulose in inedible residues with enzymes. The 2G plant at Panipat, opened in 2022, turns rice straw into ethanol -- offering farmers an income and an alternative to stubble burning without taking food off the table.','पहली पीढ़ी का एथेनॉल खाद्य फ़सलों की शर्करा और स्टार्च का उपयोग करता है; 2G एथेनॉल अखाद्य अवशेषों के सेलुलोज़ को एंज़ाइमों से तोड़ता है। 2022 में शुरू हुआ पानीपत का 2G संयंत्र धान के पुआल को एथेनॉल में बदलता है, जिससे किसानों को आय और पराली जलाने का विकल्प मिलता है, और भोजन पर असर नहीं पड़ता।','en-2g-ethanol','original_pattern_matched','Ministry of Petroleum and Natural Gas -- Pradhan Mantri JI-VAN Yojana.','draft'),
('upsc','Science & Technology','Energy & Environmental Technology','mcq','medium','Which technology produces electricity from the difference in temperature between warm surface water and cold deep water in the ocean?','कौन-सी तकनीक महासागर के गर्म सतही जल और ठंडे गहरे जल के बीच तापमान के अंतर से बिजली पैदा करती है?','{}'::jsonb,'[{"id": "a", "body": "Ocean thermal energy conversion", "body_hi": "महासागरीय तापीय ऊर्जा रूपांतरण (OTEC)", "isCorrect": true}, {"id": "b", "body": "A tidal barrage built across the mouth of a bay", "body_hi": "किसी खाड़ी के मुहाने पर बना ज्वारीय बाँध", "isCorrect": false}, {"id": "c", "body": "A wave energy converter floating on the sea surface", "body_hi": "समुद्र की सतह पर तैरता तरंग ऊर्जा परिवर्तक", "isCorrect": false}, {"id": "d", "body": "An offshore wind farm fixed to the sea bed", "body_hi": "समुद्र तल पर स्थिर अपतटीय पवन फ़ार्म", "isCorrect": false}]'::jsonb,2,0.66,'OTEC works best in the tropics, where the gap between surface and deep water is about 20 °C; warm water boils a working fluid to drive a turbine and cold water condenses it. India''s National Institute of Ocean Technology is building a plant at Kavaratti in Lakshadweep that will also desalinate water. Tidal and wave power use the motion of water, not its heat.','OTEC उष्णकटिबंध में सबसे अच्छा काम करता है, जहाँ सतही और गहरे जल का अंतर लगभग 20 °C है; गर्म पानी एक कार्यकारी द्रव को उबालकर टरबाइन चलाता है और ठंडा पानी उसे संघनित करता है। भारत का राष्ट्रीय महासागर प्रौद्योगिकी संस्थान लक्षद्वीप के कवरत्ती में एक संयंत्र बना रहा है जो पानी का विलवणीकरण भी करेगा। ज्वारीय और तरंग ऊर्जा पानी की गति का उपयोग करती हैं, उसकी ऊष्मा का नहीं।','en-otec','original_pattern_matched','National Institute of Ocean Technology -- OTEC; Ministry of Earth Sciences.','draft'),
('upsc','Science & Technology','Energy & Environmental Technology','mcq','medium','''Green steel'' refers to steel that is:','''हरित इस्पात'' (green steel) किस इस्पात को कहते हैं?','{}'::jsonb,'[{"id": "a", "body": "coated with a green-coloured paint that protects it from rusting in humid weather", "body_hi": "नम मौसम में जंग से बचाने वाले हरे रंग के पेंट से लेपित", "isCorrect": false}, {"id": "b", "body": "produced only from iron ore mined in forest areas under special environmental rules", "body_hi": "विशेष पर्यावरणीय नियमों के तहत वन क्षेत्रों में खनन किए गए लौह अयस्क से ही बना", "isCorrect": false}, {"id": "c", "body": "used exclusively for building solar panels, wind turbines and other renewable energy projects", "body_hi": "केवल सौर पैनल, पवन टरबाइन और अन्य नवीकरणीय ऊर्जा परियोजनाओं के निर्माण में प्रयुक्त", "isCorrect": false}, {"id": "d", "body": "made with far lower emissions, using hydrogen, clean power or scrap instead of coal", "body_hi": "कोयले के बजाय हाइड्रोजन, स्वच्छ बिजली या स्क्रैप से, कहीं कम उत्सर्जन के साथ बना", "isCorrect": true}]'::jsonb,2,0.66,'Steel-making with coal in blast furnaces is among the largest industrial sources of CO2. India''s green steel taxonomy of 2024 grades steel by emissions per tonne, so that low-emission steel can be labelled and preferred in public purchases -- important as the EU begins charging a carbon price at its border.','ब्लास्ट फ़र्नेस में कोयले से इस्पात बनाना CO2 के सबसे बड़े औद्योगिक स्रोतों में से है। भारत की 2024 की हरित इस्पात वर्गीकरण प्रणाली इस्पात को प्रति टन उत्सर्जन के आधार पर श्रेणी देती है, ताकि कम-उत्सर्जन वाले इस्पात को चिह्नित किया जा सके और सार्वजनिक ख़रीद में वरीयता मिले; यह इसलिए महत्त्वपूर्ण है कि EU अपनी सीमा पर कार्बन मूल्य लेना शुरू कर रहा है।','en-green-steel','original_pattern_matched','Ministry of Steel -- Green Steel Taxonomy (December 2024).','draft'),
('upsc','Science & Technology','Energy & Environmental Technology','mcq','medium','Which one of the following types of power plant usually runs at close to full output for the largest share of the year?','निम्नलिखित में से कौन-सा बिजली संयंत्र प्रायः वर्ष के सबसे बड़े भाग में लगभग पूरे उत्पादन पर चलता है?','{}'::jsonb,'[{"id": "a", "body": "Solar photovoltaic plant", "body_hi": "सौर फ़ोटोवोल्टिक संयंत्र", "isCorrect": false}, {"id": "b", "body": "Nuclear power plant", "body_hi": "नाभिकीय बिजली संयंत्र", "isCorrect": true}, {"id": "c", "body": "Onshore wind farm", "body_hi": "तटवर्ती पवन फ़ार्म", "isCorrect": false}, {"id": "d", "body": "Run-of-the-river hydro plant", "body_hi": "नदी-प्रवाह (run-of-the-river) जल संयंत्र", "isCorrect": false}]'::jsonb,2,0.66,'Nuclear plants typically achieve capacity utilisation factors of 80-90 per cent, stopping mainly for refuelling and maintenance. Solar plants in India manage about 20 per cent and wind farms 25-35 per cent, because sunlight and wind are not always available, and run-of-the-river hydro swings with the seasons.','नाभिकीय संयंत्र प्रायः 80-90 प्रतिशत क्षमता उपयोग कारक पाते हैं और मुख्य रूप से ईंधन भरने तथा रखरखाव के लिए रुकते हैं। भारत में सौर संयंत्र लगभग 20 प्रतिशत और पवन फ़ार्म 25-35 प्रतिशत तक पहुँचते हैं, क्योंकि धूप और हवा सदा उपलब्ध नहीं होतीं, और नदी-प्रवाह जलविद्युत मौसमों के साथ घटती-बढ़ती है।','en-capacity-factor-nuclear','original_pattern_matched','Central Electricity Authority -- General Review; Nuclear Power Corporation of India.','draft'),
('upsc','Science & Technology','Energy & Environmental Technology','mcq','easy','The energy of flowing water is used to produce electricity in:','बहते पानी की ऊर्जा से बिजली किसमें बनाई जाती है?','{}'::jsonb,'[{"id": "a", "body": "a thermal power plant burning coal", "body_hi": "कोयला जलाने वाला ताप बिजली संयंत्र", "isCorrect": false}, {"id": "b", "body": "a solar power plant with panels", "body_hi": "पैनलों वाला सौर बिजली संयंत्र", "isCorrect": false}, {"id": "c", "body": "a hydroelectric power plant", "body_hi": "जलविद्युत संयंत्र", "isCorrect": true}, {"id": "d", "body": "a nuclear power plant using uranium", "body_hi": "यूरेनियम का उपयोग करने वाला नाभिकीय बिजली संयंत्र", "isCorrect": false}]'::jsonb,2,0.66,'Water stored behind a dam or taken from a fast river spins turbines connected to generators; thermal and nuclear plants use steam, and solar panels use sunlight directly.','बाँध के पीछे रोका गया या तेज़ नदी से लिया गया पानी जनरेटरों से जुड़े टरबाइन घुमाता है; ताप और नाभिकीय संयंत्र भाप का उपयोग करते हैं, और सौर पैनल सीधे धूप का।','en-hydro-easy','original_pattern_matched','NCERT Science, Class X -- Sources of Energy.','draft'),
('upsc','Science & Technology','Energy & Environmental Technology','mcq','hard','A 5 kW rooftop solar system has a capacity utilisation factor of 20 per cent. About how many units (kWh) of electricity does it produce in a day on average?','5 kW की छत पर लगी सौर प्रणाली का क्षमता उपयोग कारक 20 प्रतिशत है। यह औसतन एक दिन में लगभग कितनी इकाई (kWh) बिजली पैदा करती है?','{}'::jsonb,'[{"id": "a", "body": "24", "body_hi": "24", "isCorrect": true}, {"id": "b", "body": "120", "body_hi": "120", "isCorrect": false}, {"id": "c", "body": "100", "body_hi": "100", "isCorrect": false}, {"id": "d", "body": "5", "body_hi": "5", "isCorrect": false}]'::jsonb,2,0.66,'At full output it would make 5 kW x 24 h = 120 kWh a day; a capacity utilisation factor of 20 per cent means it averages a fifth of that, 24 kWh. Choosing 120 ignores the factor, and 5 confuses power (kW) with energy (kWh).','पूरे उत्पादन पर यह प्रति दिन 5 kW x 24 घंटे = 120 kWh बनाती; 20 प्रतिशत क्षमता उपयोग कारक का अर्थ है कि यह औसतन उसका पाँचवाँ भाग, 24 kWh, देती है। 120 चुनना कारक की अनदेखी है, और 5 शक्ति (kW) को ऊर्जा (kWh) से मिला देता है।','en-solar-output-numerical','original_pattern_matched','Ministry of New and Renewable Energy.','draft'),
('upsc','Science & Technology','Energy & Environmental Technology','assertion_reason','medium','Consider the following statements:','निम्नलिखित कथनों पर विचार कीजिए:','{"assertion": "Blending ethanol into petrol reduces India''s crude oil import bill.", "assertion_hi": "पेट्रोल में एथेनॉल मिलाने से भारत का कच्चे तेल का आयात बिल घटता है।", "reason": "Ethanol replaces part of the petrol that would otherwise be refined from imported crude.", "reason_hi": "एथेनॉल उस पेट्रोल के एक भाग का स्थान लेता है जो अन्यथा आयातित कच्चे तेल से परिष्कृत होता।", "ar_labels": "statement", "closing": "Which one of the following is correct in respect of the above statements?", "closing_hi": "उपर्युक्त कथनों के संदर्भ में, निम्नलिखित में से कौन-सा एक सही है?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Both Statement-I and Statement-II are correct and Statement-II is the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं और कथन-II, कथन-I की सही व्याख्या है", "isCorrect": true}, {"id": "b", "body": "Both Statement-I and Statement-II are correct and Statement-II is not the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं, किंतु कथन-II, कथन-I की सही व्याख्या नहीं है", "isCorrect": false}, {"id": "c", "body": "Statement-I is correct but Statement-II is incorrect", "body_hi": "कथन-I सही है, किंतु कथन-II गलत है", "isCorrect": false}, {"id": "d", "body": "Statement-I is incorrect but Statement-II is correct", "body_hi": "कथन-I गलत है, किंतु कथन-II सही है", "isCorrect": false}]'::jsonb,2,0.66,'Both statements are correct and Statement-II explains Statement-I. Because nearly 90 per cent of India''s crude is imported, every litre of domestically distilled ethanol saves foreign exchange; the government estimates the programme has saved over a lakh crore rupees since 2014.','दोनों कथन सही हैं और कथन-II कथन-I की व्याख्या करता है। चूँकि भारत का लगभग 90 प्रतिशत कच्चा तेल आयात होता है, देश में आसवित हर लीटर एथेनॉल विदेशी मुद्रा बचाता है; सरकार का अनुमान है कि इस कार्यक्रम ने 2014 से एक लाख करोड़ रुपये से अधिक बचाए हैं।','en-ethanol-imports','original_pattern_matched','Ministry of Petroleum and Natural Gas -- Ethanol Blended Petrol Programme.','draft'),
('upsc','Science & Technology','Energy & Environmental Technology','assertion_reason','medium','Consider the following statements:','निम्नलिखित कथनों पर विचार कीजिए:','{"assertion": "Electric buses can reduce air pollution in cities.", "assertion_hi": "इलेक्ट्रिक बसें शहरों में वायु प्रदूषण घटा सकती हैं।", "reason": "Electric buses cost more to run per kilometre than diesel buses.", "reason_hi": "इलेक्ट्रिक बसें प्रति किलोमीटर चलाने में डीज़ल बसों से महँगी पड़ती हैं।", "ar_labels": "statement", "closing": "Which one of the following is correct in respect of the above statements?", "closing_hi": "उपर्युक्त कथनों के संदर्भ में, निम्नलिखित में से कौन-सा एक सही है?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Both Statement-I and Statement-II are correct and Statement-II is the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं और कथन-II, कथन-I की सही व्याख्या है", "isCorrect": false}, {"id": "b", "body": "Both Statement-I and Statement-II are correct and Statement-II is not the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं, किंतु कथन-II, कथन-I की सही व्याख्या नहीं है", "isCorrect": false}, {"id": "c", "body": "Statement-I is correct but Statement-II is incorrect", "body_hi": "कथन-I सही है, किंतु कथन-II गलत है", "isCorrect": true}, {"id": "d", "body": "Statement-I is incorrect but Statement-II is correct", "body_hi": "कथन-I गलत है, किंतु कथन-II सही है", "isCorrect": false}]'::jsonb,2,0.66,'Statement-I is correct but Statement-II is incorrect. E-buses cost more to buy, but electricity is cheaper than diesel and motors need less maintenance, so running costs per kilometre are lower -- which is why cities lease them under ''gross cost contracts'' that pay the operator per kilometre run.','कथन-I सही है पर कथन-II गलत है। ई-बसें ख़रीदने में महँगी हैं, पर बिजली डीज़ल से सस्ती है और मोटरों को कम रखरखाव चाहिए, इसलिए प्रति किलोमीटर चलाने की लागत कम है; इसीलिए शहर उन्हें ''सकल लागत अनुबंधों'' पर पट्टे पर लेते हैं, जिनमें संचालक को प्रति किलोमीटर भुगतान होता है।','en-electric-buses','original_pattern_matched','Ministry of Heavy Industries -- PM e-Bus Sewa; Convergence Energy Services Limited.','draft'),
('upsc','Science & Technology','Energy & Environmental Technology','assertion_reason','easy','Consider the following statements:','निम्नलिखित कथनों पर विचार कीजिए:','{"assertion": "Solar water heaters save electricity.", "assertion_hi": "सौर जल तापक (solar water heaters) बिजली बचाते हैं।", "reason": "They use sunlight instead of electricity to heat water.", "reason_hi": "वे पानी गर्म करने के लिए बिजली के बजाय धूप का उपयोग करते हैं।", "ar_labels": "statement", "closing": "Which one of the following is correct in respect of the above statements?", "closing_hi": "उपर्युक्त कथनों के संदर्भ में, निम्नलिखित में से कौन-सा एक सही है?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Both Statement-I and Statement-II are correct and Statement-II is the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं और कथन-II, कथन-I की सही व्याख्या है", "isCorrect": true}, {"id": "b", "body": "Both Statement-I and Statement-II are correct and Statement-II is not the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं, किंतु कथन-II, कथन-I की सही व्याख्या नहीं है", "isCorrect": false}, {"id": "c", "body": "Statement-I is correct but Statement-II is incorrect", "body_hi": "कथन-I सही है, किंतु कथन-II गलत है", "isCorrect": false}, {"id": "d", "body": "Statement-I is incorrect but Statement-II is correct", "body_hi": "कथन-I गलत है, किंतु कथन-II सही है", "isCorrect": false}]'::jsonb,2,0.66,'Both statements are correct and Statement-II explains Statement-I: dark collectors on the roof absorb sunlight and warm the water that flows through them.','दोनों कथन सही हैं और कथन-II कथन-I की व्याख्या करता है: छत पर लगे गहरे रंग के संग्राहक धूप सोखते हैं और उनसे बहने वाले पानी को गर्म करते हैं।','en-solar-water-heater-easy','original_pattern_matched','NCERT Science, Class X -- Sources of Energy.','draft'),
('upsc','Science & Technology','Energy & Environmental Technology','assertion_reason','hard','Consider the following statements:','निम्नलिखित कथनों पर विचार कीजिए:','{"assertion": "A kilogram of hydrogen contains less energy than a kilogram of petrol.", "assertion_hi": "एक किलोग्राम हाइड्रोजन में एक किलोग्राम पेट्रोल से कम ऊर्जा होती है।", "reason": "Hydrogen has a very low density, so it must be compressed or liquefied to be stored.", "reason_hi": "हाइड्रोजन का घनत्व बहुत कम है, इसलिए उसे संग्रहीत करने के लिए संपीड़ित या द्रवित करना पड़ता है।", "ar_labels": "statement", "closing": "Which one of the following is correct in respect of the above statements?", "closing_hi": "उपर्युक्त कथनों के संदर्भ में, निम्नलिखित में से कौन-सा एक सही है?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Both Statement-I and Statement-II are correct and Statement-II is the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं और कथन-II, कथन-I की सही व्याख्या है", "isCorrect": false}, {"id": "b", "body": "Both Statement-I and Statement-II are correct and Statement-II is not the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं, किंतु कथन-II, कथन-I की सही व्याख्या नहीं है", "isCorrect": false}, {"id": "c", "body": "Statement-I is correct but Statement-II is incorrect", "body_hi": "कथन-I सही है, किंतु कथन-II गलत है", "isCorrect": false}, {"id": "d", "body": "Statement-I is incorrect but Statement-II is correct", "body_hi": "कथन-I गलत है, किंतु कथन-II सही है", "isCorrect": true}]'::jsonb,2,0.66,'Statement-I is incorrect but Statement-II is correct. By weight, hydrogen holds nearly three times as much energy as petrol -- about 120 megajoules per kilogram against about 44 -- but a kilogram of it takes up so much space that it must be stored at very high pressure or at -253 °C, which is the main difficulty in using it as a fuel.','कथन-I गलत है पर कथन-II सही है। भार के हिसाब से हाइड्रोजन में पेट्रोल से लगभग तीन गुना ऊर्जा होती है, लगभग 120 मेगाजूल प्रति किलोग्राम के मुक़ाबले लगभग 44; पर इसका एक किलोग्राम इतनी जगह घेरता है कि इसे बहुत ऊँचे दाब पर या -253 °C पर रखना पड़ता है, और ईंधन के रूप में इसके उपयोग की मुख्य कठिनाई यही है।','en-hydrogen-energy-density','original_pattern_matched','Ministry of New and Renewable Energy; International Energy Agency -- The Future of Hydrogen.','draft'),
('upsc','Science & Technology','Defence, Aerospace & Security Technology','statement_based','medium','Consider the following statements about missiles:','प्रक्षेपास्त्रों (missiles) के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["BrahMos is a supersonic cruise missile developed jointly by India and Russia.", "Prithvi is a surface-to-surface ballistic missile.", "Cruise missiles travel on a high ballistic arc above the atmosphere."], "statements_hi": ["ब्रह्मोस भारत और रूस द्वारा संयुक्त रूप से विकसित एक पराध्वनिक (supersonic) क्रूज़ प्रक्षेपास्त्र है।", "पृथ्वी एक सतह-से-सतह बैलिस्टिक प्रक्षेपास्त्र है।", "क्रूज़ प्रक्षेपास्त्र वायुमंडल के ऊपर एक ऊँचे बैलिस्टिक चाप पर चलते हैं।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct: BrahMos, named after the Brahmaputra and the Moskva, flies at nearly three times the speed of sound and has been exported to the Philippines; Prithvi was the first missile of the Integrated Guided Missile Development Programme. Statement 3 is wrong: cruise missiles fly within the atmosphere, powered all the way and often hugging the ground to avoid radar; it is ballistic missiles that follow a high arc after their engines burn out.','कथन 1 और 2 सही हैं: ब्रह्मपुत्र और मॉस्कवा के नाम पर बना ब्रह्मोस ध्वनि की गति से लगभग तीन गुना तेज़ उड़ता है और फ़िलीपींस को निर्यात किया गया है; पृथ्वी एकीकृत निर्देशित प्रक्षेपास्त्र विकास कार्यक्रम का पहला प्रक्षेपास्त्र था। कथन 3 गलत है: क्रूज़ प्रक्षेपास्त्र वायुमंडल के भीतर उड़ते हैं, पूरे रास्ते इंजन से संचालित होते हैं और प्रायः रडार से बचने के लिए ज़मीन के क़रीब चलते हैं; ऊँचे चाप का अनुसरण बैलिस्टिक प्रक्षेपास्त्र अपने इंजन बुझने के बाद करते हैं।','df-missile-types','original_pattern_matched','Defence Research and Development Organisation; BrahMos Aerospace.','draft'),
('upsc','Science & Technology','Defence, Aerospace & Security Technology','statement_based','medium','Consider the following statements about ''Mission Divyastra'':','''मिशन दिव्यास्त्र'' के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["It tested the BrahMos missile fitted with MIRV technology.", "MIRV technology lets a single missile carry several warheads aimed at different targets.", "With this test India became the first country in the world to develop MIRV technology."], "statements_hi": ["इसमें MIRV तकनीक से युक्त ब्रह्मोस प्रक्षेपास्त्र का परीक्षण किया गया।", "MIRV तकनीक एक ही प्रक्षेपास्त्र को अलग-अलग लक्ष्यों पर निशाना साधने वाले कई आयुध (warheads) ले जाने देती है।", "इस परीक्षण के साथ भारत MIRV तकनीक विकसित करने वाला विश्व का पहला देश बना।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": true}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 2 is correct: MIRV stands for Multiple Independently targetable Re-entry Vehicle. Statement 1 is wrong: Mission Divyastra, in March 2024, tested the Agni-V ballistic missile with MIRV technology, not the BrahMos cruise missile. Statement 3 is wrong: the United States and the Soviet Union developed MIRVs in the 1970s; India joined a small group of countries with the capability.','केवल कथन 2 सही है: MIRV का अर्थ है बहु-स्वतंत्र-लक्ष्य-योग्य पुनःप्रवेश वाहन (Multiple Independently targetable Re-entry Vehicle)। कथन 1 गलत है: मार्च 2024 में मिशन दिव्यास्त्र ने MIRV तकनीक के साथ अग्नि-V बैलिस्टिक प्रक्षेपास्त्र का परीक्षण किया, ब्रह्मोस क्रूज़ प्रक्षेपास्त्र का नहीं। कथन 3 गलत है: संयुक्त राज्य अमेरिका और सोवियत संघ ने 1970 के दशक में MIRV विकसित किए; भारत इस क्षमता वाले देशों के एक छोटे समूह में शामिल हुआ।','df-mission-divyastra-mirv','original_pattern_matched','Ministry of Defence; Defence Research and Development Organisation -- Mission Divyastra (March 2024).','draft'),
('upsc','Science & Technology','Defence, Aerospace & Security Technology','statement_based','medium','Consider the following statements about hypersonic technology:','हाइपरसोनिक तकनीक के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Hypersonic weapons travel at more than five times the speed of sound.", "India flight-tested a long-range hypersonic missile in November 2024.", "Scramjet engines take in oxygen from the air as they fly."], "statements_hi": ["हाइपरसोनिक हथियार ध्वनि की गति से पाँच गुना से अधिक गति से चलते हैं।", "भारत ने नवंबर 2024 में एक लंबी दूरी के हाइपरसोनिक प्रक्षेपास्त्र का उड़ान परीक्षण किया।", "स्क्रैमजेट इंजन उड़ते समय हवा से ऑक्सीजन लेते हैं।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": true}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'All three statements are correct. Speeds above Mach 5 leave defences little time to react. A scramjet, a supersonic-combustion ramjet, has no moving parts and burns fuel in air rushing through it at supersonic speed; because it carries no oxygen of its own, it is lighter than a rocket, but it works only once the vehicle is already flying very fast.','तीनों कथन सही हैं। मैक 5 से ऊपर की गति रक्षा प्रणालियों को प्रतिक्रिया के लिए बहुत कम समय देती है। स्क्रैमजेट, यानी पराध्वनिक-दहन रैमजेट, में कोई चलने वाला पुर्ज़ा नहीं होता और यह पराध्वनिक गति से उससे होकर जाती हवा में ईंधन जलाता है; चूँकि यह अपनी ऑक्सीजन नहीं ले जाता, यह रॉकेट से हल्का है, पर तभी काम करता है जब वाहन पहले से बहुत तेज़ उड़ रहा हो।','df-hypersonic-scramjet','original_pattern_matched','Defence Research and Development Organisation -- long-range hypersonic missile test (November 2024); Defence Research and Development Organisation -- HSTDV.','draft'),
('upsc','Science & Technology','Defence, Aerospace & Security Technology','statement_based','medium','Consider the following statements about air defence systems:','वायु रक्षा प्रणालियों के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["The S-400 air defence system was developed by France.", "Akash is an indigenous surface-to-air missile system.", "The Iron Dome system was developed by India."], "statements_hi": ["S-400 वायु रक्षा प्रणाली फ़्रांस ने विकसित की।", "आकाश एक स्वदेशी सतह-से-हवा प्रक्षेपास्त्र प्रणाली है।", "आयरन डोम प्रणाली भारत ने विकसित की।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": true}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 2 is correct: Akash, developed by DRDO, is in service with the Army and Air Force and has been exported. Statement 1 is wrong: the S-400 Triumf is a Russian long-range system, which India bought under a 2018 deal. Statement 3 is wrong: Iron Dome is an Israeli system designed to intercept short-range rockets and shells.','केवल कथन 2 सही है: DRDO द्वारा विकसित आकाश थल सेना और वायु सेना की सेवा में है और निर्यात भी हुई है। कथन 1 गलत है: S-400 ट्रायम्फ़ एक रूसी लंबी दूरी की प्रणाली है, जिसे भारत ने 2018 के एक सौदे के तहत ख़रीदा। कथन 3 गलत है: आयरन डोम एक इज़राइली प्रणाली है जो कम दूरी के रॉकेटों और गोलों को रोकने के लिए बनी है।','df-air-defence','original_pattern_matched','Ministry of Defence; Defence Research and Development Organisation -- Akash.','draft'),
('upsc','Science & Technology','Defence, Aerospace & Security Technology','statement_based','medium','Consider the following statements about the Indian Navy:','भारतीय नौसेना के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["INS Vikrant is India''s first indigenously built aircraft carrier.", "INS Arihant is a nuclear-powered submarine that carries ballistic missiles.", "The Kalvari-class submarines built under Project-75 are nuclear-powered."], "statements_hi": ["INS विक्रांत भारत का पहला स्वदेशी रूप से निर्मित विमानवाहक पोत है।", "INS अरिहंत एक नाभिकीय ऊर्जा चालित पनडुब्बी है जो बैलिस्टिक प्रक्षेपास्त्र ले जाती है।", "प्रोजेक्ट-75 के तहत बनी कलवरी-श्रेणी की पनडुब्बियाँ नाभिकीय ऊर्जा चालित हैं।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct: Vikrant, built at Cochin Shipyard and commissioned in 2022, made India one of the few countries able to design and build a carrier; Arihant gives the sea-based leg of India''s nuclear deterrent. Statement 3 is wrong: the six Kalvari boats, built in Mumbai with French help on the Scorpene design, are diesel-electric submarines.','कथन 1 और 2 सही हैं: कोचीन शिपयार्ड में बना और 2022 में कमीशन हुआ विक्रांत भारत को उन कुछ देशों में ले आया जो विमानवाहक पोत डिज़ाइन कर और बना सकते हैं; अरिहंत भारत के नाभिकीय प्रतिरोध का समुद्र-आधारित पक्ष देती है। कथन 3 गलत है: स्कॉर्पीन डिज़ाइन पर फ़्रांसीसी सहायता से मुंबई में बनी छह कलवरी पनडुब्बियाँ डीज़ल-इलेक्ट्रिक पनडुब्बियाँ हैं।','df-navy-platforms','original_pattern_matched','Ministry of Defence -- Indian Navy.','draft'),
('upsc','Science & Technology','Defence, Aerospace & Security Technology','statement_based','medium','Consider the following statements about military aircraft:','सैन्य विमानों के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Tejas is a heavy strategic bomber.", "The Rafale jets flown by the Indian Air Force were built in the United States.", "Stealth aircraft are invisible to the naked eye."], "statements_hi": ["तेजस एक भारी रणनीतिक बमवर्षक है।", "भारतीय वायु सेना द्वारा उड़ाए जाने वाले राफ़ेल विमान संयुक्त राज्य अमेरिका में बने।", "स्टेल्थ विमान नंगी आँखों से दिखाई नहीं देते।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": true}]'::jsonb,2,0.66,'None of the statements is correct. Tejas is a light combat aircraft, designed by the Aeronautical Development Agency and built by HAL. The Rafale is made by Dassault Aviation of France. Stealth aircraft can be seen perfectly well; their shape and coatings make them very hard to detect on radar.','कोई भी कथन सही नहीं है। तेजस एक हल्का लड़ाकू विमान है, जिसे वैमानिकी विकास एजेंसी ने डिज़ाइन किया और HAL ने बनाया। राफ़ेल फ़्रांस की डसॉल्ट एविएशन बनाती है। स्टेल्थ विमान पूरी तरह दिखाई देते हैं; उनका आकार और लेप उन्हें रडार पर पहचानना बहुत कठिन बनाते हैं।','df-aircraft-none','original_pattern_matched','Ministry of Defence; Hindustan Aeronautics Limited; Aeronautical Development Agency.','draft'),
('upsc','Science & Technology','Defence, Aerospace & Security Technology','statement_based','medium','Consider the following statements about drones in India:','भारत में ड्रोनों के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["The Namo Drone Didi scheme gives drones to women''s self-help groups to offer spraying and other farm services.", "Under the Drone Rules, 2021, a remote pilot certificate is needed to fly every drone, including nano drones.", "India banned the import of foreign drones in 2022, except for specified purposes.", "Under the Drone Rules, 2021, drones may fly freely in red zones without permission."], "statements_hi": ["नमो ड्रोन दीदी योजना महिला स्वयं सहायता समूहों को छिड़काव और अन्य कृषि सेवाएँ देने के लिए ड्रोन देती है।", "ड्रोन नियम, 2021 के तहत नैनो ड्रोन सहित हर ड्रोन उड़ाने के लिए दूरस्थ पायलट प्रमाणपत्र चाहिए।", "भारत ने 2022 में, निर्दिष्ट उद्देश्यों को छोड़कर, विदेशी ड्रोनों के आयात पर रोक लगाई।", "ड्रोन नियम, 2021 के तहत रेड ज़ोन में ड्रोन बिना अनुमति के स्वतंत्र रूप से उड़ सकते हैं।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "Only three", "body_hi": "केवल तीन", "isCorrect": false}, {"id": "d", "body": "All four", "body_hi": "सभी चार", "isCorrect": false}]'::jsonb,2,0.66,'Only two -- statements 1 and 3 -- are correct: the scheme aims to raise SHG incomes while cutting spraying costs, and the import ban, with exemptions for research, defence and security, was meant to build domestic manufacturing alongside a PLI scheme for drones. Statement 2 is wrong: nano drones, and micro drones used for non-commercial purposes, need no remote pilot certificate. Statement 4 is wrong: red zones, such as areas near airports and military sites, are no-fly zones; green zones need no permission, and yellow zones need clearance.','केवल दो, यानी कथन 1 और 3, सही हैं: योजना का उद्देश्य छिड़काव की लागत घटाते हुए SHG की आय बढ़ाना है, और आयात पर रोक, जिसमें अनुसंधान, रक्षा और सुरक्षा के लिए छूट है, ड्रोनों के लिए PLI योजना के साथ घरेलू विनिर्माण बढ़ाने के लिए थी। कथन 2 गलत है: नैनो ड्रोन, और ग़ैर-व्यावसायिक उद्देश्यों के लिए प्रयुक्त माइक्रो ड्रोन, को दूरस्थ पायलट प्रमाणपत्र नहीं चाहिए। कथन 4 गलत है: हवाई अड्डों और सैन्य स्थलों के पास के क्षेत्र जैसे रेड ज़ोन उड़ान-वर्जित क्षेत्र हैं; ग्रीन ज़ोन में अनुमति नहीं चाहिए, और येलो ज़ोन में मंज़ूरी चाहिए।','df-drones-india','original_pattern_matched','Ministry of Civil Aviation -- Drone Rules, 2021 and Digital Sky; Ministry of Agriculture and Farmers Welfare -- Namo Drone Didi.','draft'),
('upsc','Science & Technology','Defence, Aerospace & Security Technology','statement_based','easy','Consider the following statements:','निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["The Indian Air Force operates fighter aircraft.", "Submarines can travel under water."], "statements_hi": ["भारतीय वायु सेना लड़ाकू विमान संचालित करती है।", "पनडुब्बियाँ पानी के नीचे चल सकती हैं।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": true}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2,0.66,'Both statements are correct: submarines dive by letting water into ballast tanks and surface by blowing it out with compressed air.','दोनों कथन सही हैं: पनडुब्बियाँ गिट्टी टंकियों (ballast tanks) में पानी भरकर गोता लगाती हैं और संपीड़ित हवा से उसे निकालकर सतह पर आती हैं।','df-air-force-submarines-easy','original_pattern_matched','Ministry of Defence.','draft'),
('upsc','Science & Technology','Defence, Aerospace & Security Technology','statement_based','easy','Consider the following statements:','निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["DRDO develops technologies for the armed forces.", "A missile and a satellite are the same thing."], "statements_hi": ["DRDO सशस्त्र बलों के लिए प्रौद्योगिकियाँ विकसित करता है।", "प्रक्षेपास्त्र और उपग्रह एक ही चीज़ हैं।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": true}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 1 is correct. Statement 2 is wrong: a missile is a guided weapon that flies to a target, while a satellite is placed in orbit and circles the Earth; both may use rocket technology.','केवल कथन 1 सही है। कथन 2 गलत है: प्रक्षेपास्त्र एक निर्देशित हथियार है जो किसी लक्ष्य तक उड़ता है, जबकि उपग्रह कक्षा में रखा जाता है और पृथ्वी की परिक्रमा करता है; दोनों में रॉकेट तकनीक का उपयोग हो सकता है।','df-drdo-missile-satellite-easy','original_pattern_matched','Defence Research and Development Organisation.','draft'),
('upsc','Science & Technology','Defence, Aerospace & Security Technology','statement_based','easy','Consider the following statements:','निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Tanks are used mainly by the Navy.", "Bulletproof jackets protect soldiers from gunfire."], "statements_hi": ["टैंकों का उपयोग मुख्य रूप से नौसेना करती है।", "बुलेटप्रूफ़ जैकेट सैनिकों को गोलीबारी से बचाती हैं।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": true}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 2 is correct. Statement 1 is wrong: tanks are armoured fighting vehicles of the Army; the Navy operates ships and submarines.','केवल कथन 2 सही है। कथन 1 गलत है: टैंक थल सेना के बख़्तरबंद लड़ाकू वाहन हैं; नौसेना जहाज़ और पनडुब्बियाँ चलाती है।','df-tanks-jackets-easy','original_pattern_matched','Ministry of Defence.','draft'),
('upsc','Science & Technology','Defence, Aerospace & Security Technology','statement_based','hard','Consider the following statements about India''s defence industry:','भारत के रक्षा उद्योग के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["India''s defence exports crossed ₹20,000 crore in 2023-24.", "The iDEX programme funds start-ups and innovators to develop defence technology.", "India is the world''s largest arms exporter."], "statements_hi": ["भारत का रक्षा निर्यात 2023-24 में ₹20,000 करोड़ पार कर गया।", "iDEX कार्यक्रम रक्षा प्रौद्योगिकी विकसित करने के लिए स्टार्ट-अप और नवप्रवर्तकों को धन देता है।", "भारत विश्व का सबसे बड़ा हथियार निर्यातक है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct: exports -- of BrahMos missiles, artillery, radars, patrol vessels and components -- have grown many times over the past decade, and iDEX (Innovations for Defence Excellence), launched in 2018, gives grants through open challenges. Statement 3 is wrong: the United States, Russia and France dominate exports; India remains one of the world''s largest arms importers.','कथन 1 और 2 सही हैं: ब्रह्मोस प्रक्षेपास्त्रों, तोपख़ाने, रडारों, गश्ती पोतों और पुर्ज़ों का निर्यात पिछले दशक में कई गुना बढ़ा है, और 2018 में शुरू हुआ iDEX (रक्षा उत्कृष्टता के लिए नवाचार) खुली चुनौतियों के ज़रिए अनुदान देता है। कथन 3 गलत है: निर्यात पर संयुक्त राज्य अमेरिका, रूस और फ़्रांस का प्रभुत्व है; भारत विश्व के सबसे बड़े हथियार आयातकों में बना हुआ है।','df-defence-industry','original_pattern_matched','Ministry of Defence -- Department of Defence Production; Stockholm International Peace Research Institute.','draft'),
('upsc','Science & Technology','Defence, Aerospace & Security Technology','statement_based','hard','Consider the following statements about India''s nuclear deterrent:','भारत के नाभिकीय प्रतिरोध (nuclear deterrent) के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["India''s nuclear doctrine includes a commitment to ''no first use''.", "India has a nuclear triad of land-based missiles, aircraft and submarines.", "India''s nuclear forces are managed by the Strategic Forces Command."], "statements_hi": ["भारत के नाभिकीय सिद्धांत में ''पहले उपयोग नहीं'' (no first use) की प्रतिबद्धता शामिल है।", "भारत के पास भूमि-आधारित प्रक्षेपास्त्रों, विमानों और पनडुब्बियों की नाभिकीय त्रयी (triad) है।", "भारत के नाभिकीय बलों का प्रबंधन सामरिक बल कमान (Strategic Forces Command) करती है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": true}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'All three statements are correct. Under the doctrine of 2003, India will not use nuclear weapons first and keeps a ''credible minimum deterrent'', with massive retaliation if attacked. The Strategic Forces Command, set up in 2003, operates the weapons under the civilian-led Nuclear Command Authority, whose political council is chaired by the Prime Minister.','तीनों कथन सही हैं। 2003 के सिद्धांत के तहत भारत नाभिकीय हथियारों का पहले उपयोग नहीं करेगा और ''विश्वसनीय न्यूनतम प्रतिरोध'' रखता है, और हमला होने पर भारी प्रतिशोध करेगा। 2003 में बनी सामरिक बल कमान असैनिक-नेतृत्व वाले नाभिकीय कमान प्राधिकरण के अंतर्गत हथियारों का संचालन करती है, जिसकी राजनीतिक परिषद की अध्यक्षता प्रधानमंत्री करते हैं।','df-nuclear-doctrine','original_pattern_matched','Cabinet Committee on Security -- Review of India''s Nuclear Doctrine (January 2003).','draft'),
('upsc','Science & Technology','Defence, Aerospace & Security Technology','mcq','medium','''Kavach'', developed for the Indian Railways, is:','भारतीय रेलवे के लिए विकसित ''कवच'' क्या है?','{}'::jsonb,'[{"id": "a", "body": "a bulletproof coating fitted to the windows of trains that run in border areas", "body_hi": "सीमावर्ती क्षेत्रों में चलने वाली रेलगाड़ियों की खिड़कियों पर लगी बुलेटप्रूफ़ परत", "isCorrect": false}, {"id": "b", "body": "a mobile app that lets passengers report crimes on trains to the railway police", "body_hi": "एक मोबाइल ऐप जो यात्रियों को रेलगाड़ियों में अपराधों की सूचना रेलवे पुलिस को देने देता है", "isCorrect": false}, {"id": "c", "body": "a system of fences and cameras that stops people and cattle from crossing the tracks", "body_hi": "बाड़ और कैमरों की एक प्रणाली जो लोगों और मवेशियों को पटरियाँ पार करने से रोकती है", "isCorrect": false}, {"id": "d", "body": "an automatic train protection system that applies the brakes to prevent collisions", "body_hi": "एक स्वचालित रेल सुरक्षा प्रणाली जो टक्कर रोकने के लिए ब्रेक लगा देती है", "isCorrect": true}]'::jsonb,2,0.66,'Kavach, developed by the Research Designs and Standards Organisation with Indian firms, uses radio links between locomotives, stations and track equipment; if a driver passes a red signal or overspeeds, it brakes the train automatically. It is certified to the highest safety integrity level and is being rolled out across the network.','अनुसंधान अभिकल्प और मानक संगठन (RDSO) द्वारा भारतीय कंपनियों के साथ विकसित कवच इंजनों, स्टेशनों और पटरी उपकरणों के बीच रेडियो संपर्कों का उपयोग करता है; यदि चालक लाल सिग्नल पार करे या गति सीमा तोड़े, तो यह अपने-आप गाड़ी रोक देता है। यह उच्चतम सुरक्षा अखंडता स्तर पर प्रमाणित है और पूरे नेटवर्क में लगाया जा रहा है।','df-kavach','original_pattern_matched','Ministry of Railways -- Kavach; Research Designs and Standards Organisation.','draft'),
('upsc','Science & Technology','Defence, Aerospace & Security Technology','mcq','medium','The Advanced Medium Combat Aircraft (AMCA) is:','उन्नत मध्यम लड़ाकू विमान (AMCA) क्या है?','{}'::jsonb,'[{"id": "a", "body": "a transport aircraft bought from abroad to carry troops and cargo", "body_hi": "सैनिकों और माल को ले जाने के लिए विदेश से ख़रीदा गया एक परिवहन विमान", "isCorrect": false}, {"id": "b", "body": "India''s planned fifth-generation stealth fighter", "body_hi": "भारत का प्रस्तावित पाँचवीं पीढ़ी का स्टेल्थ लड़ाकू विमान", "isCorrect": true}, {"id": "c", "body": "a trainer aircraft used to teach new pilots to fly", "body_hi": "नए पायलटों को उड़ाना सिखाने के लिए प्रयुक्त एक प्रशिक्षण विमान", "isCorrect": false}, {"id": "d", "body": "an unmanned drone used for watching the border from high altitude", "body_hi": "ऊँचाई से सीमा की निगरानी के लिए प्रयुक्त एक मानवरहित ड्रोन", "isCorrect": false}]'::jsonb,2,0.66,'The twin-engine AMCA is being developed by the Aeronautical Development Agency, with private industry invited to partner in building it. Fifth-generation features include stealth shaping, internal weapons bays, sensor fusion and the ability to cruise at supersonic speed.','दोहरे इंजन वाला AMCA वैमानिकी विकास एजेंसी विकसित कर रही है, और इसके निर्माण में निजी उद्योग को भागीदार के रूप में आमंत्रित किया गया है। पाँचवीं पीढ़ी की विशेषताओं में स्टेल्थ आकार, आंतरिक हथियार खाने, सेंसर संलयन और पराध्वनिक गति पर उड़ते रहने की क्षमता शामिल हैं।','df-amca','original_pattern_matched','Ministry of Defence -- Aeronautical Development Agency.','draft'),
('upsc','Science & Technology','Defence, Aerospace & Security Technology','mcq','medium','India''s anti-satellite missile test of 2019 was named:','भारत के 2019 के उपग्रह-रोधी (anti-satellite) प्रक्षेपास्त्र परीक्षण का नाम क्या था?','{}'::jsonb,'[{"id": "a", "body": "Operation Shakti", "body_hi": "ऑपरेशन शक्ति", "isCorrect": false}, {"id": "b", "body": "Operation Sankalp", "body_hi": "ऑपरेशन संकल्प", "isCorrect": false}, {"id": "c", "body": "Mission Shakti", "body_hi": "मिशन शक्ति", "isCorrect": true}, {"id": "d", "body": "Mission Sudarshan Chakra", "body_hi": "मिशन सुदर्शन चक्र", "isCorrect": false}]'::jsonb,2,0.66,'Mission Shakti destroyed a live Indian satellite in low Earth orbit with a DRDO interceptor, making India the fourth country with this ability. Operation Shakti was the code name of the 1998 nuclear tests at Pokhran, Operation Sankalp a naval deployment to protect shipping in the Gulf region in 2019, and Sudarshan Chakra the air-defence shield announced in 2025. The name is shared with an unrelated women''s empowerment scheme.','मिशन शक्ति ने DRDO के एक अवरोधक से निम्न भू-कक्षा में एक सक्रिय भारतीय उपग्रह को नष्ट किया, जिससे भारत यह क्षमता रखने वाला चौथा देश बना। ऑपरेशन शक्ति पोखरण में 1998 के नाभिकीय परीक्षणों का कूट नाम था, ऑपरेशन संकल्प 2019 में खाड़ी क्षेत्र में जहाज़ों की रक्षा के लिए नौसेना की तैनाती, और सुदर्शन चक्र 2025 में घोषित वायु-रक्षा कवच। यही नाम महिला सशक्तिकरण की एक असंबद्ध योजना का भी है।','df-mission-shakti-asat','original_pattern_matched','Defence Research and Development Organisation -- Mission Shakti (March 2019).','draft'),
('upsc','Science & Technology','Defence, Aerospace & Security Technology','mcq','easy','Which of India''s armed forces operates submarines?','भारत की कौन-सी सशस्त्र सेना पनडुब्बियाँ संचालित करती है?','{}'::jsonb,'[{"id": "a", "body": "The Navy", "body_hi": "नौसेना", "isCorrect": true}, {"id": "b", "body": "The Army", "body_hi": "थल सेना", "isCorrect": false}, {"id": "c", "body": "The Air Force", "body_hi": "वायु सेना", "isCorrect": false}, {"id": "d", "body": "The Border Security Force", "body_hi": "सीमा सुरक्षा बल", "isCorrect": false}]'::jsonb,2,0.66,'Submarines belong to the Navy; the Border Security Force is a central armed police force that guards the land borders with Pakistan and Bangladesh.','पनडुब्बियाँ नौसेना की होती हैं; सीमा सुरक्षा बल एक केंद्रीय सशस्त्र पुलिस बल है जो पाकिस्तान और बांग्लादेश से लगी भूमि सीमाओं की रक्षा करता है।','df-navy-submarines-easy','original_pattern_matched','Ministry of Defence.','draft'),
('upsc','Science & Technology','Defence, Aerospace & Security Technology','mcq','hard','Hypersonic glide vehicles are harder to intercept than ordinary ballistic missile warheads mainly because they:','हाइपरसोनिक ग्लाइड वाहनों को साधारण बैलिस्टिक प्रक्षेपास्त्र आयुधों से रोकना कठिन क्यों है? मुख्य रूप से इसलिए कि वे:','{}'::jsonb,'[{"id": "a", "body": "are too small to be seen by any of the radars now in service anywhere in the whole world", "body_hi": "इतने छोटे हैं कि विश्व में कहीं भी सेवा में मौजूद कोई रडार उन्हें नहीं देख सकता", "isCorrect": false}, {"id": "b", "body": "carry decoy satellites that confuse the early-warning systems of the target country", "body_hi": "लक्ष्य देश की पूर्व-चेतावनी प्रणालियों को भ्रमित करने वाले नक़ली उपग्रह ले जाते हैं", "isCorrect": false}, {"id": "c", "body": "travel more slowly than ballistic warheads, so interceptors overshoot them in flight", "body_hi": "बैलिस्टिक आयुधों से धीमे चलते हैं, इसलिए अवरोधक उड़ान में उनसे आगे निकल जाते हैं", "isCorrect": false}, {"id": "d", "body": "fly very fast at lower altitudes and can change course, unlike warheads on a fixed arc", "body_hi": "बहुत तेज़, कम ऊँचाई पर उड़ते हैं और मार्ग बदल सकते हैं, जबकि आयुध निश्चित चाप पर चलते हैं", "isCorrect": true}]'::jsonb,2,0.66,'A ballistic warhead follows a high, predictable path, so defences can calculate where to meet it. A glide vehicle, released by a rocket, skims the upper atmosphere at more than Mach 5, below the view of many radars until late, and can manoeuvre -- so interceptors have little warning and no fixed path to aim at.','बैलिस्टिक आयुध एक ऊँचे, पूर्वानुमेय मार्ग पर चलता है, इसलिए रक्षा प्रणालियाँ गणना कर सकती हैं कि उसे कहाँ रोकें। रॉकेट से छोड़ा गया ग्लाइड वाहन मैक 5 से अधिक गति पर ऊपरी वायुमंडल को छूता हुआ चलता है, देर तक कई रडारों की दृष्टि से नीचे रहता है और युक्तिचालन कर सकता है; इसलिए अवरोधकों को बहुत कम चेतावनी मिलती है और निशाना साधने के लिए कोई निश्चित मार्ग नहीं होता।','df-hypersonic-glide-interception','original_pattern_matched','Defence Research and Development Organisation; Stockholm International Peace Research Institute.','draft'),
('upsc','Science & Technology','Defence, Aerospace & Security Technology','assertion_reason','medium','Consider the following statements:','निम्नलिखित कथनों पर विचार कीजिए:','{"assertion": "India imports a large share of its major weapons.", "assertion_hi": "भारत अपने प्रमुख हथियारों का बड़ा हिस्सा आयात करता है।", "reason": "India''s defence exports have risen in recent years.", "reason_hi": "हाल के वर्षों में भारत का रक्षा निर्यात बढ़ा है।", "ar_labels": "statement", "closing": "Which one of the following is correct in respect of the above statements?", "closing_hi": "उपर्युक्त कथनों के संदर्भ में, निम्नलिखित में से कौन-सा एक सही है?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Both Statement-I and Statement-II are correct and Statement-II is the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं और कथन-II, कथन-I की सही व्याख्या है", "isCorrect": false}, {"id": "b", "body": "Both Statement-I and Statement-II are correct and Statement-II is not the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं, किंतु कथन-II, कथन-I की सही व्याख्या नहीं है", "isCorrect": true}, {"id": "c", "body": "Statement-I is correct but Statement-II is incorrect", "body_hi": "कथन-I सही है, किंतु कथन-II गलत है", "isCorrect": false}, {"id": "d", "body": "Statement-I is incorrect but Statement-II is correct", "body_hi": "कथन-I गलत है, किंतु कथन-II सही है", "isCorrect": false}]'::jsonb,2,0.66,'Both statements are correct, but Statement-II does not explain Statement-I. India relies on imports because domestic industry has long lacked the technology and scale for many complex systems such as engines and advanced fighters; growing exports are a separate trend, driven by policy support and new products, and do not explain the imports.','दोनों कथन सही हैं, पर कथन-II कथन-I की व्याख्या नहीं करता। भारत आयात पर इसलिए निर्भर है कि घरेलू उद्योग के पास लंबे समय से इंजन और उन्नत लड़ाकू विमान जैसी कई जटिल प्रणालियों के लिए तकनीक और पैमाना नहीं रहा; बढ़ता निर्यात एक अलग प्रवृत्ति है, जो नीतिगत समर्थन और नए उत्पादों से आई है, और आयात की व्याख्या नहीं करती।','df-imports-exports','original_pattern_matched','Stockholm International Peace Research Institute -- Trends in International Arms Transfers; Ministry of Defence.','draft')
